(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-089"]={"sura":89,"name_ar":"الفجر","name_en":"Al-Fajr","verses":30,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":30,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=14\" class=\"link\">89:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:14 ஐ பார்க்கவும்"},"14":{"html":"<strong>மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<strong>தொழுகையில் ஸூரத்துல் ஃபஜ்ர் ஓதுதல்</strong><br />\r\n<br />\r\nமுஆத் (ரழி) அவர்கள் ஒருமுறை தொழுகை நடத்தினார்கள்; அப்போது ஒரு மனிதர் வந்து அவர்களுடன் தொழுகையில் இணைந்துகொண்டார் என ஜாபிர் (ரழி) அவர்கள் அறிவிக்கும் செய்தியை நஸாயீ பதிவு செய்துள்ளார்கள். முஆத் (ரழி) அவர்கள் தொழுகையை நீட்டித் தொழுததால், அந்த மனிதர் தனியாகச் சென்று பள்ளிவாசலின் ஒரு ஓரத்தில் தொழுதுவிட்டுத் திரும்பிச் சென்றார். இதுபற்றி முஆத் (ரழி) அவர்களுக்குத் தெரியவந்தபோது, \"அவர் ஒரு நயவஞ்சகர்\" என்று கூறினார்கள். பிறகு, நடந்தவற்றை முஆத் (ரழி) அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் தெரிவித்தார்கள். நபி (ஸல்) அவர்கள் அந்த இளைஞரிடம் அது பற்றிக் கேட்டபோது, அவர், \"அல்லாஹ்வின் தூதரே! நான் அவர்களுடன் தொழ வந்தேன், ஆனால் அவர்கள் தொழுகையை எனக்கு மிகவும் நீட்டிவிட்டார்கள். எனவே நான் அவர்களை விட்டுவிட்டுப் பள்ளிவாசலின் ஓரத்தில் தொழுதேன். பிறகு எனது பெண் ஒட்டகத்திற்குத் தீனி போடச் சென்றேன்\" என்று பதிலளித்தார். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَفَتَّانٌ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُعَاذُ؟</span> <span class=\"quran-arabic-font text-success\">أَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَبِّحِ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالشَّمْسِ</span> <span class=\"quran-arabic-font text-success\">وَضُحَاهَا</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْفَجْرِ</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">يَغْشَى</span> »<br />\r\n<br />\r\n(முஆதே! நீர் குழப்பம் விளைவிக்கிறீரா? நீர் ஏன் (‘உமது மிக மேலான இறைவனின் திருப்பெயரைத் துதிப்பீராக’), (‘சூரியன் மற்றும் அதன் பிரகாசத்தின் மீது சத்தியமாக’), (‘விடியற்காலையின் மீது சத்தியமாக’), மற்றும் (‘இரவு மூடிக்கொள்ளும் போது அதன் மீது சத்தியமாக’) ஆகியவற்றை ஓதவில்லை?)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>அல்-ஃபஜ்ர் மற்றும் அதற்குப் பின் வருபவற்றின் விளக்கம்</strong><br />\r\n<br />\r\nஅல்-ஃபஜ்ர் என்பது விடியற்காலையைக் குறிக்கும் என்பது அனைவரும் அறிந்ததே. இதையே அலீ (ரழி), இப்னு அப்பாஸ் (ரழி), இக்ரிமா (ரழி), முஜாஹித் (ரழி) மற்றும் அஸ்-ஸுத்தீ (ரழி) ஆகியோர் கூறியுள்ளார்கள். மஸ்ரூக் மற்றும் முஹம்மது பின் கஃப் (ரழி) ஆகியோரிடமிருந்து, அல்-ஃபஜ்ர் என்பது குறிப்பாக 'அன்-நஹ்ர்' எனும் தியாகத் திருநாளைக் குறிக்கிறது என்றும், அது பத்து இரவுகளில் இறுதியானது என்றும் அறிவிக்கப்பட்டுள்ளது. 'பத்து இரவுகள்' என்பது துல்ஹஜ் மாதத்தின் முதல் பத்து நாட்களைக் குறிக்கும். இப்னு அப்பாஸ் (ரழி), இப்னு ஸுபைர் (ரழி), முஜாஹித் (ரழி) மற்றும் ஸலஃபுகள் முதல் பிற்காலத்தவர்கள் வரை பலர் இவ்வாறு கூறியுள்ளனர். இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள் என ஸஹீஹ் அல்-புகாரியில் இவ்வாறு உறுதிப்படுத்தப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَيَّامٍ</span> <span class=\"quran-arabic-font text-success\">الْعَمَلُ</span> <span class=\"quran-arabic-font text-success\">الصَّالِحُ</span> <span class=\"quran-arabic-font text-success\">أَحَبُّ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">هذِهِ</span> <span class=\"quran-arabic-font text-success\">الْأَيَّام</span>»<br />\r\n<br />\r\n(இந்த (பத்து) நாட்களில் செய்யப்படும் நற்செயல்களை விட அல்லாஹ்வுக்கு மிகவும் விருப்பமான வேறு எந்த நாட்களும் இல்லை.) அதாவது துல்ஹஜ் மாதத்தின் முதல் பத்து நாட்கள். அப்போது (ஸஹாபாக்கள்), \"அல்லாஹ்வின் பாதையில் ஜிஹாத் செய்வதை விடவுமா?\" என்று கேட்டார்கள். அதற்கு நபி (ஸல்) அவர்கள் பதிலளித்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">الْجِهَادُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللهِ،</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">رَجُلًا</span> <span class=\"quran-arabic-font text-success\">خَرَجَ</span> <span class=\"quran-arabic-font text-success\">بِنَفْسِهِ</span> <span class=\"quran-arabic-font text-success\">وَمَالِهِ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَرْجِعْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">بِشَيْء</span>»<br />\r\n<br />\r\n(அல்லாஹ்வின் பாதையில் ஜிஹாத் செய்வதை விடவும் இதுவே சிறந்தது; ஆனால் ஒரு மனிதன் தனது உயிருடனும் செல்வத்துடனும் ஜிஹாதுக்குப் புறப்பட்டுச் சென்று, இரண்டையுமே இழந்து எதையும் கொண்டு திரும்பாமல் இருப்பவனைத் தவிர.)<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالشَّفْعِ</span> <span class=\"quran-arabic-font text-success\">وَالْوَتْرِ</span><br />\r\n<br />\r\n(மேலும் இரட்டை மீதும், ஒற்றை மீதும் சத்தியமாக.) \"இரட்டை (அஷ்-ஷஃப்வு) என்பது தியாகத் திருநாளாகும் (யவ்முன் நஹ்ர்). ஒற்றை (அல்-வித்ர்) என்பது அராஃபா நாளாகும் (யவ்மு அரஃபா)\" என்று இப்னு அப்பாஸ் (ரழி) கூறினார்கள். இக்ரிமா மற்றும் அ-ழஹ்ஹாக் ஆகியோரும் இவ்வாறே கூறினார்கள். \"படைப்புகள் அனைத்தும் இரட்டையாகும். அல்லாஹ் ஒருவனே ஒற்றையாவான்\" என்று முஜாஹித் (ரழி) கூறினார்கள்.<br />\r\n<br />\r\n<strong>இரவின் விளக்கம்</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">يَسْرِ</span><br />\r\n<br />\r\n(மேலும் இரவு செல்லும்போது அதன் மீது சத்தியமாக.) இது குறித்து இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இரவு விலகிச் செல்லும்போது\" என்று கூறியதாக அல்-அவ்ஃபீ அறிவிக்கின்றார்கள். அப்துல்லாஹ் பின் ஸுபைர் (ரழி) அவர்கள், \"இரவின் சில பகுதிகள் மற்ற பகுதிகளை அகற்றிவிட்டுச் செல்லும்போது\" என்று இதற்கு விளக்கமளித்தார்கள். முஜாஹித், அபூ அல்-ஆலியா, கதாதா மற்றும் ஸைத் பின் அஸ்லம், இப்னு ஸைத் ஆகியோரிடமிருந்து மாலிக் அறிவிக்கிறார்கள்; இவர்கள் அனைவரும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">يَسْرِ</span><br />\r\n<br />\r\n(இரவு செல்லும்போது) என்பதற்கு \"இரவு நகர்ந்து செல்லும்போது\" என்று பொருள் கூறினார்கள். அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">قَسَمٌ</span> <span class=\"quran-arabic-font text-success\">لِّذِى</span> <span class=\"quran-arabic-font text-success\">حِجْرٍ</span><br />\r\n<br />\r\n(நிச்சயமாக இவற்றில் அறிவுடையோருக்கு (ஹிஜ்ர் உடையோருக்கு) போதுமான சத்தியம் இருக்கிறதல்லவா!) அதாவது புத்திசாலித்தனம், சரியான பகுத்தறிவு, புரிதல் மற்றும் மார்க்க ஞானம் கொண்டவர்களுக்கு இதில் போதிய சான்று உள்ளது. அறிவு ஒரு நபரை அவருக்குப் பொருத்தமற்ற செயல்கள் மற்றும் பேச்சுகளிலிருந்து தடுப்பதால் அதற்கு 'ஹிஜ்ர்' (தடுத்தல்) என்று பெயர் வந்தது. இதிலிருந்துதான் 'ஹிஜ்ர் அல்-பைத்' என்ற பெயரும் உருவானது; ஏனெனில் அது தவாஃப் செய்பவர் அஷ்-ஷாம் திசையிலுள்ள சுவரை ஒட்டிச் செல்வதைத் தடுக்கிறது. மேலும் 'ஹிஜ்ர் அல்-யமாமா' (புறாக் கூண்டு) என்பதும் தடுத்தல் என்ற பொருளிலிருந்தே வந்தது. ஒரு நீதிபதி ஒருவரது செல்வத்தைப் பயன்படுத்துவதை முடக்கும்போது, \"ஹஜர அல்-ஹாகிம் (நீதிபதி தடுத்தார்)\" என்று கூறப்படுகிறது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">حِجْراً</span> <span class=\"quran-arabic-font text-success\">مَّحْجُوراً</span><br />\r\n<br />\r\n(மேலும் அவர்கள், \"விலக்கப்பட்ட தடையாகும்\" (ஹிஜ்ர் மஹ்ஜூர்) என்று கூறுவார்கள்.) (<a href=\"qurandisp.php?sura=25&ayah=22\" class=\"link\">25:22</a>). இந்த உதாரணங்கள் அனைத்தும் வெவ்வேறு சூழல்களைக் குறிக்கின்றன என்றாலும் அவற்றின் அடிப்படைப் பொருள் ஒன்றுதான். இங்கு குறிப்பிடப்பட்டுள்ள சத்தியம், வணக்க வழிபாட்டு நேரங்களையும் ஹஜ், தொழுகை போன்ற வணக்கச் செயல்களையும் குறிக்கிறது. அல்லாஹ்வின் இறையச்சமுள்ள அடியார்கள் அவனது திருப்தியை நாடி, பணிவோடு செய்யும் இத்தகைய வணக்கங்கள் அவனை நெருங்குவதற்கான வழிகளாகும்.<br />\r\n<br />\r\n<strong>ஆது கூட்டத்தாரின் அழிவைப் பற்றிக் குறிப்பிடுதல்</strong><br />\r\n<br />\r\nஇறையச்சமுள்ள மக்களையும் அவர்களின் வணக்கங்களையும் குறிப்பிட்ட பிறகு, அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">فَعَلَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">بِعَادٍ</span><br />\r\n<br />\r\n(உமது இறைவன் ஆது கூட்டத்தாரை என்ன செய்தான் என்பதை நீர் பார்க்கவில்லையா?) இவர்கள் கலகக்காரர்களாகவும், கீழ்ப்படியாதவர்களாகவும், ஆணவம் கொண்டவர்களாகவும் இருந்தார்கள். அல்லாஹ்வின் கட்டளைகளை மீறி, அவனது தூதர்களையும் வேதங்களையும் நிராகரித்தார்கள். எனவே, அவர்களை அல்லாஹ் எப்படி அழித்தான், நிர்மூலமாக்கிப் பிற்காலத்தவர் பேசும் ஒரு பாடமாக ஆக்கினான் என்பதை அல்லாஹ் இங்கே குறிப்பிடுகிறான். அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">فَعَلَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">بِعَادٍ</span> - <span class=\"quran-arabic-font text-success\">إِرَمَ</span> <span class=\"quran-arabic-font text-success\">ذَاتِ</span> <span class=\"quran-arabic-font text-success\">الْعِمَادِ</span><br />\r\n<br />\r\n(உமது இறைவன் ஆது கூட்டத்தாரை - தூண்களையுடைய இரம் (நகர) வாசிகளை - என்ன செய்தான் என்பதை நீர் பார்க்கவில்லையா?) இவர்கள் ஆது கூட்டத்தின் முதல் மக்கள் ஆவர். இவர்கள் ஆத் பின் இரம் பின் அவ்ஸ் பின் ஸாம் பின் நூஹ் (அலை) அவர்களின் வழித்தோன்றல்கள் என்று இப்னு இஸ்ஹாக் கூறுகிறார். இவர்களிடமே அல்லாஹ் தனது தூதர் ஹூத் (அலை) அவர்களை அனுப்பினான். ஆனால் அவர்கள் அவரைப் பொய்யாக்கி எதிர்த்தார்கள். எனவே அல்லாஹ் ஹூத் (அலை) அவர்களையும் அவருடன் ஈமான் கொண்டவர்களையும் காப்பாற்றிவிட்டு, மற்றவர்களைக் கடும் சீற்றத்துடன் வீசிய காற்றினால் அழித்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَخَّرَهَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">لَيَالٍ</span> <span class=\"quran-arabic-font text-success\">وَثَمَـنِيَةَ</span> <span class=\"quran-arabic-font text-success\">أَيَّامٍ</span> <span class=\"quran-arabic-font text-success\">حُسُوماً</span> <span class=\"quran-arabic-font text-success\">فَتَرَى</span> <span class=\"quran-arabic-font text-success\">الْقَوْمَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">صَرْعَى</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْجَازُ</span> <span class=\"quran-arabic-font text-success\">نَخْلٍ</span> <span class=\"quran-arabic-font text-success\">خَاوِيَةٍ</span> - <span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">بَاقِيَةٍ</span><br />\r\n<br />\r\n(அதனை அல்லாஹ் தொடர்ந்து ஏழு இரவுகளும் எட்டுப் பகல்களும் அவர்கள் மீது ஏவினான்; அப்போது அந்த மக்கள் வேரோடு சாய்ந்த பேரீச்சை மரத்தின் உடல் பகுதிகளைப் போல் வீழ்ந்து கிடப்பதை நீர் பார்த்திருப்பீர். அவர்களில் எவராவது எஞ்சியிருப்பதை நீர் காண்கிறீரா?) (<a href=\"qurandisp.php?sura=69&ayah=7\" class=\"link\">69:7</a>-8). விசுவாசிகள் அவர்களின் முடிவிலிருந்து பாடம் பெற வேண்டும் என்பதற்காக அல்லாஹ் அவர்களின் வரலாற்றைக் குர்ஆனில் பல இடங்களில் குறிப்பிட்டுள்ளான். பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِرَمَ</span> <span class=\"quran-arabic-font text-success\">ذَاتِ</span> <span class=\"quran-arabic-font text-success\">الْعِمَادِ</span><br />\r\n<br />\r\n(தூண்களையுடைய இரம்.) இது அவர்கள் யார் என்பதைத் தெளிவுபடுத்தும் கூடுதல் விளக்கமாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَاتِ</span> <span class=\"quran-arabic-font text-success\">الْعِمَادِ</span><br />\r\n<br />\r\n(தூண்களையுடைய) என்பதற்கு விளக்கம் என்னவெனில், அவர்கள் உறுதியான தூண்களின் மேல் அமைக்கப்பட்ட உயர்ந்த வீடுகளில் வாழ்ந்தார்கள். அவர்கள் தங்கள் காலத்தில் உடல் வலிமையிலும் அதிகாரத்திலும் மற்றவர்களை விட மிக ஆற்றல் வாய்ந்தவர்களாக இருந்தார்கள். எனவே, ஹூத் (அலை) அவர்கள் அல்லாஹ் அவர்களுக்கு வழங்கிய இந்த அருளை நினைவூட்டி, அவர்களைப் படைத்த இறைவனுக்குக் கீழ்ப்படிவதற்காக இந்த வலிமையைப் பயன்படுத்துமாறு கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاذكُرُواْ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">جَعَلَكُمْ</span> <span class=\"quran-arabic-font text-success\">خُلَفَآءَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">قَوْمِ</span> <span class=\"quran-arabic-font text-success\">نُوحٍ</span> <span class=\"quran-arabic-font text-success\">وَزَادَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْخَلْقِ</span> <span class=\"quran-arabic-font text-success\">بَسْطَةً</span> <span class=\"quran-arabic-font text-success\">فَاذْكُرُواْ</span> <span class=\"quran-arabic-font text-success\">ءَالآءَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تُفْلِحُونَ</span><br />\n<br />\n\r<br />\n(நூஹ் (அலை) உடைய சமூகத்தாருக்குப் பின் உங்களை அவன் பிரதிநிதிகளாக ஆக்கியதையும், உடல் அமைப்பில் உங்களை அவன் மேம்படுத்தியதையும் நினைத்துப் பாருங்கள். நீங்கள் வெற்றி பெறுவதற்காக அல்லாஹ்வின் அருட்கொடைகளை நினைவுகூருங்கள்.) (<a href=\"qurandisp.php?sura=7&ayah=69\" class=\"link\">7:69</a>). அல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">عَادٌ</span> <span class=\"quran-arabic-font text-success\">فَاسْتَكْبَرُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">بِغَيْرِ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">مِنَّا</span> <span class=\"quran-arabic-font text-success\">قُوَّةً</span> <span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَرَوْاْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَهُمْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">قُوَّةً</span><br />\r\n<br />\r\n(ஆது சமூகத்தாரோ, அவர்கள் பூமியில் அநியாயமாகப் பெருமையடித்து, \"வலிமையில் எங்களை விடச் சிறந்தவர் யார்?\" என்று கேட்டார்கள். அவர்களைப் படைத்த அல்லாஹ், அவர்களை விட வலிமையில் சிறந்தவன் என்பதை அவர்கள் உணரவில்லையா?) (<a href=\"qurandisp.php?sura=41&ayah=15\" class=\"link\">41:15</a>). மேலும் அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يُخْلَقْ</span> <span class=\"quran-arabic-font text-success\">مِثْلُهَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبِلَادِ</span><br />\r\n<br />\r\n(அவர்களைப் போன்றவர்கள் தேசங்களில் (இதற்கு முன்) படைக்கப்படவில்லை.) அதாவது அவர்களின் வலிமை, அதிகாரம் மற்றும் உடல் அமைப்பைப் போன்றவர்கள் அந்தத் தேசத்தில் வேறு யாரும் படைக்கப்பட்டதில்லை. முஜாஹித் (ரழி) அவர்கள், \"இரம் என்பது ஒரு பழங்கால சமூகமாகும்; அவர்களே ஆது கூட்டத்தின் முதல் மக்கள்\" என்று கூறினார்கள். கதாதா பின் திஆமா மற்றும் அஸ்-ஸுத்தீ ஆகிய இருவரும், \"நிச்சயமாக இரம் என்பது ஆது கூட்டத்தாரின் ஆட்சி பீடத்தைக் குறிக்கிறது\" என்றனர். இக்கூற்று வலிமையானதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يُخْلَقْ</span> <span class=\"quran-arabic-font text-success\">مِثْلُهَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبِلَادِ</span><br />\r\n<br />\r\n(அவர்களைப் போன்றவர்கள் தேசங்களில் படைக்கப்படவில்லை.) என்பதில் உள்ள பிரதிப்பெயர்ச்சொல் அவர்கள் அமைத்த தூண்களைக் குறிப்பதாக இப்னு ஸைத் கருதினார். \"அவர்கள் மலைகளுக்கு இடையில் மிக உயர்ந்த தூண்களைக் கட்டினார்கள், அதுபோன்றவை அந்தத் தேசத்தில் இதற்கு முன் கட்டப்பட்டதில்லை\" என்று அவர் கூறினார். இருப்பினும், கதாதா மற்றும் இப்னு ஜரீர் ஆகியோர் இது ஆது கோத்திரத்தைக் குறிக்கிறது என்றே கருதினார்கள். அதாவது, அந்தக் காலத்தில் அவர்களைப் போன்ற ஒரு பலமான கோத்திரம் பூமியில் படைக்கப்பட்டதில்லை என்பதே இதன் பொருள். இதுவே சரியான கருத்தாகும். இப்னு ஸைதின் கருத்து பலவீனமானது; ஏனெனில் அல்லாஹ் தூண்களை நாடியிருந்தால் \"உருவாக்கப்படவில்லை\" என்று கூறியிருப்பான், ஆனால் அவன் \"படைக்கப்படவில்லை\" (லெம் யுக்லக்) என்றே கூறியுள்ளான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يُخْلَقْ</span> <span class=\"quran-arabic-font text-success\">مِثْلُهَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبِلَادِ</span><br />\r\n<br />\r\n(அவர்களைப் போன்றவர்கள் தேசங்களில் படைக்கப்படவில்லை.) பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَثَمُودَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">جَابُواْ</span> <span class=\"quran-arabic-font text-success\">الصَّخْرَ</span> <span class=\"quran-arabic-font text-success\">بِالْوَادِ</span><br />\r\n<br />\r\n(பள்ளத்தாக்கில் பாறைகளைக் குடைந்த (ஜாபு) ஸமூத் கூட்டத்தாரையும்.) அதாவது அவர்கள் பள்ளத்தாக்குகளில் உள்ள பாறைகளை வெட்டி வீடுகளாக அமைத்தார்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள், \"அவர்கள் பாறைகளைச் செதுக்கிக் குடைந்தார்கள்\" என்று கூறினார்கள். முஜாஹித், கதாதா, அத்-தஹ்ஹாக் மற்றும் இப்னு ஸைத் ஆகியோரும் இதையே கூறினார்கள். அரபு மொழியில் ஆடையைத் தைப்பதற்காகத் துளை இடுவதை 'ஜைப்' என்பார்கள்; அதுவும் 'ஜாபு' என்ற சொல்லிலிருந்தே வந்தது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَنْحِتُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْجِبَالِ</span> <span class=\"quran-arabic-font text-success\">بُيُوتاً</span> <span class=\"quran-arabic-font text-success\">فَـرِهِينَ</span><br />\r\n<br />\r\n(மேலும் நீங்கள் மலைகளைத் திறமையுடன் குடைந்து வீடுகளை அமைத்துக் கொள்கிறீர்கள்.) (<a href=\"qurandisp.php?sura=26&ayah=149\" class=\"link\">26:149</a>)<br />\r\n<br />\r\n<strong>ஃபிர்அவ்னைப் பற்றிய ஒரு குறிப்பு</strong><br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَفِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">ذِى</span> <span class=\"quran-arabic-font text-success\">الْأَوْتَادِ</span><br />\r\n<br />\r\n(மேலும் ஆணிகளுடைய (அல்-அவ்தாத்) ஃபிர்அவ்னையும்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"அல்-அவ்தாத் என்பது அவனது கட்டளைகளைச் செயல்படுத்திய அவனது படைகளைக் குறிக்கும்\" என்று கூறியதாக அல்-அவ்ஃபீ அறிவிக்கின்றார்கள். ஃபிர்அவ்ன் மக்களைத் தண்டிக்கும்போது அவர்களின் கைகளிலும் கால்களிலும் இரும்பு முளைகளை (ஆணிகளை) அடித்துத் தொங்கவிடுவான் என்றும் ஒரு கருத்து உள்ளது. முஜாஹித் (ரழி) அவர்களும், \"அவன் மக்களை முளைகளில் அடித்துத் தண்டிப்பான்\" என்று கூறினார்கள். ஸஈத் பின் ஜுபைர், அல்-ஹஸன் மற்றும் அஸ்-ஸுத்தீ ஆகியோரும் இதையே கூறியுள்ளனர். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">طَغَوْاْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبِلَادِ</span> - <span class=\"quran-arabic-font text-success\">فَأَكْثَرُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">الْفَسَادَ</span><br />\r\n<br />\r\n(அவர்கள் தேசங்களில் வரம்பு மீறிச் சென்றார்கள். மேலும் அதில் பெரும் குழப்பத்தை விளைவித்தார்கள்.) அதாவது அவர்கள் ஆணவத்துடன் கலகம் செய்து, பூமியில் சீர்கேடுகளை உண்டாக்கி மக்களுக்குத் தீங்கு செய்தார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَصَبَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">سَوْطَ</span> <span class=\"quran-arabic-font text-success\">عَذَابٍ</span><br />\r\n<br />\r\n(ஆகவே, உமது இறைவன் அவர்கள் மீது பல்வேறு வகையான கடுமையான வேதனைகளை இறக்கினான்.) அதாவது, அல்லாஹ் வானத்திலிருந்து அவர்கள் மீது தண்டனையை இறக்கினான்; குற்றவாளிகளால் தப்பிக்க முடியாத ஒரு வேதனையால் அவர்களை அழித்தான்.<br />\r\n<br />\r\n<strong>இறைவன் எப்போதும் கண்காணிப்பவன்</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">لَبِالْمِرْصَادِ</span><br />\r\n<br />\r\n(நிச்சயமாக, உமது இறைவன் எப்போதும் கண்காணிப்பவனாக இருக்கிறான்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"அவன் அனைத்தையும் செவியேற்கிறான், பார்க்கிறான்\" என்று இதற்கு விளக்கமளித்தார்கள். அதாவது, தனது படைப்புகள் செய்வதை அல்லாஹ் உன்னிப்பாகக் கவனிக்கிறான்; அவர்கள் செய்த செயல்களுக்கு ஏற்ப இவ்வுலகிலும் மறுமையிலும் அவர்களுக்குப் பிரதிபலன் வழங்குவான். அல்லாஹ் அனைத்துப் படைப்புகளையும் தன் முன் கொண்டு வந்து நீதியுடன் தீர்ப்பளிப்பான். அவன் அநீதிக்கும் கொடுங்கோன்மைக்கும் அப்பாற்பட்டவன் என்பதால், ஒவ்வொருவருக்கும் அவரவர் தகுதிக்குரிய கூலியை வழங்குவான்.<br />\r\n<br />","text":"மக்காவில் அருளப்பட்டது\n\r\n\n\r\nதொழுகையில் ஸூரத்துல் ஃபஜ்ர் ஓதுதல்\n\r\n\n\r\nமுஆத் (ரழி) அவர்கள் ஒருமுறை தொழுகை நடத்தினார்கள்; அப்போது ஒரு மனிதர் வந்து அவர்களுடன் தொழுகையில் இணைந்துகொண்டார் என ஜாபிர் (ரழி) அவர்கள் அறிவிக்கும் செய்தியை நஸாயீ பதிவு செய்துள்ளார்கள். முஆத் (ரழி) அவர்கள் தொழுகையை நீட்டித் தொழுததால், அந்த மனிதர் தனியாகச் சென்று பள்ளிவாசலின் ஒரு ஓரத்தில் தொழுதுவிட்டுத் திரும்பிச் சென்றார். இதுபற்றி முஆத் (ரழி) அவர்களுக்குத் தெரியவந்தபோது, \"அவர் ஒரு நயவஞ்சகர்\" என்று கூறினார்கள். பிறகு, நடந்தவற்றை முஆத் (ரழி) அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் தெரிவித்தார்கள். நபி (ஸல்) அவர்கள் அந்த இளைஞரிடம் அது பற்றிக் கேட்டபோது, அவர், \"அல்லாஹ்வின் தூதரே! நான் அவர்களுடன் தொழ வந்தேன், ஆனால் அவர்கள் தொழுகையை எனக்கு மிகவும் நீட்டிவிட்டார்கள். எனவே நான் அவர்களை விட்டுவிட்டுப் பள்ளிவாசலின் ஓரத்தில் தொழுதேன். பிறகு எனது பெண் ஒட்டகத்திற்குத் தீனி போடச் சென்றேன்\" என்று பதிலளித்தார். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَفَتَّانٌ يَا مُعَاذُ؟ أَيْنَ أَنْتَ مِنْ\n\r\n\n\r\nسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى\n\r\n\n\r\nوَالشَّمْسِ وَضُحَاهَا\n\r\n\n\r\nوَالْفَجْرِ\n\r\n\n\r\nوَاللَّيْلِ إِذَا يَغْشَى »\n\r\n\n\r\n(முஆதே! நீர் குழப்பம் விளைவிக்கிறீரா? நீர் ஏன் (‘உமது மிக மேலான இறைவனின் திருப்பெயரைத் துதிப்பீராக’), (‘சூரியன் மற்றும் அதன் பிரகாசத்தின் மீது சத்தியமாக’), (‘விடியற்காலையின் மீது சத்தியமாக’), மற்றும் (‘இரவு மூடிக்கொள்ளும் போது அதன் மீது சத்தியமாக’) ஆகியவற்றை ஓதவில்லை?)\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nஅல்-ஃபஜ்ர் மற்றும் அதற்குப் பின் வருபவற்றின் விளக்கம்\n\r\n\n\r\nஅல்-ஃபஜ்ர் என்பது விடியற்காலையைக் குறிக்கும் என்பது அனைவரும் அறிந்ததே. இதையே அலீ (ரழி), இப்னு அப்பாஸ் (ரழி), இக்ரிமா (ரழி), முஜாஹித் (ரழி) மற்றும் அஸ்-ஸுத்தீ (ரழி) ஆகியோர் கூறியுள்ளார்கள். மஸ்ரூக் மற்றும் முஹம்மது பின் கஃப் (ரழி) ஆகியோரிடமிருந்து, அல்-ஃபஜ்ர் என்பது குறிப்பாக 'அன்-நஹ்ர்' எனும் தியாகத் திருநாளைக் குறிக்கிறது என்றும், அது பத்து இரவுகளில் இறுதியானது என்றும் அறிவிக்கப்பட்டுள்ளது. 'பத்து இரவுகள்' என்பது துல்ஹஜ் மாதத்தின் முதல் பத்து நாட்களைக் குறிக்கும். இப்னு அப்பாஸ் (ரழி), இப்னு ஸுபைர் (ரழி), முஜாஹித் (ரழி) மற்றும் ஸலஃபுகள் முதல் பிற்காலத்தவர்கள் வரை பலர் இவ்வாறு கூறியுள்ளனர். இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள் என ஸஹீஹ் அல்-புகாரியில் இவ்வாறு உறுதிப்படுத்தப்பட்டுள்ளது:\n\r\n\n\r\n«مَا مِنْ أَيَّامٍ الْعَمَلُ الصَّالِحُ أَحَبُّ إِلَى اللهِ فِيهِنَّ مِنْ هذِهِ الْأَيَّام»\n\r\n\n\r\n(இந்த (பத்து) நாட்களில் செய்யப்படும் நற்செயல்களை விட அல்லாஹ்வுக்கு மிகவும் விருப்பமான வேறு எந்த நாட்களும் இல்லை.) அதாவது துல்ஹஜ் மாதத்தின் முதல் பத்து நாட்கள். அப்போது (ஸஹாபாக்கள்), \"அல்லாஹ்வின் பாதையில் ஜிஹாத் செய்வதை விடவுமா?\" என்று கேட்டார்கள். அதற்கு நபி (ஸல்) அவர்கள் பதிலளித்தார்கள்:\n\r\n\n\r\n«وَلَا الْجِهَادُ فِي سَبِيلِ اللهِ، إِلَّا رَجُلًا خَرَجَ بِنَفْسِهِ وَمَالِهِ ثُمَّ لَمْ يَرْجِعْ مِنْ ذلِكَ بِشَيْء»\n\r\n\n\r\n(அல்லாஹ்வின் பாதையில் ஜிஹாத் செய்வதை விடவும் இதுவே சிறந்தது; ஆனால் ஒரு மனிதன் தனது உயிருடனும் செல்வத்துடனும் ஜிஹாதுக்குப் புறப்பட்டுச் சென்று, இரண்டையுமே இழந்து எதையும் கொண்டு திரும்பாமல் இருப்பவனைத் தவிர.)\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nوَالشَّفْعِ وَالْوَتْرِ\n\r\n\n\r\n(மேலும் இரட்டை மீதும், ஒற்றை மீதும் சத்தியமாக.) \"இரட்டை (அஷ்-ஷஃப்வு) என்பது தியாகத் திருநாளாகும் (யவ்முன் நஹ்ர்). ஒற்றை (அல்-வித்ர்) என்பது அராஃபா நாளாகும் (யவ்மு அரஃபா)\" என்று இப்னு அப்பாஸ் (ரழி) கூறினார்கள். இக்ரிமா மற்றும் அ-ழஹ்ஹாக் ஆகியோரும் இவ்வாறே கூறினார்கள். \"படைப்புகள் அனைத்தும் இரட்டையாகும். அல்லாஹ் ஒருவனே ஒற்றையாவான்\" என்று முஜாஹித் (ரழி) கூறினார்கள்.\n\r\n\n\r\nஇரவின் விளக்கம்\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nوَاللَّيْلِ إِذَا يَسْرِ\n\r\n\n\r\n(மேலும் இரவு செல்லும்போது அதன் மீது சத்தியமாக.) இது குறித்து இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இரவு விலகிச் செல்லும்போது\" என்று கூறியதாக அல்-அவ்ஃபீ அறிவிக்கின்றார்கள். அப்துல்லாஹ் பின் ஸுபைர் (ரழி) அவர்கள், \"இரவின் சில பகுதிகள் மற்ற பகுதிகளை அகற்றிவிட்டுச் செல்லும்போது\" என்று இதற்கு விளக்கமளித்தார்கள். முஜாஹித், அபூ அல்-ஆலியா, கதாதா மற்றும் ஸைத் பின் அஸ்லம், இப்னு ஸைத் ஆகியோரிடமிருந்து மாலிக் அறிவிக்கிறார்கள்; இவர்கள் அனைவரும்:\n\r\n\n\r\nوَاللَّيْلِ إِذَا يَسْرِ\n\r\n\n\r\n(இரவு செல்லும்போது) என்பதற்கு \"இரவு நகர்ந்து செல்லும்போது\" என்று பொருள் கூறினார்கள். அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nهَلْ فِى ذَلِكَ قَسَمٌ لِّذِى حِجْرٍ\n\r\n\n\r\n(நிச்சயமாக இவற்றில் அறிவுடையோருக்கு (ஹிஜ்ர் உடையோருக்கு) போதுமான சத்தியம் இருக்கிறதல்லவா!) அதாவது புத்திசாலித்தனம், சரியான பகுத்தறிவு, புரிதல் மற்றும் மார்க்க ஞானம் கொண்டவர்களுக்கு இதில் போதிய சான்று உள்ளது. அறிவு ஒரு நபரை அவருக்குப் பொருத்தமற்ற செயல்கள் மற்றும் பேச்சுகளிலிருந்து தடுப்பதால் அதற்கு 'ஹிஜ்ர்' (தடுத்தல்) என்று பெயர் வந்தது. இதிலிருந்துதான் 'ஹிஜ்ர் அல்-பைத்' என்ற பெயரும் உருவானது; ஏனெனில் அது தவாஃப் செய்பவர் அஷ்-ஷாம் திசையிலுள்ள சுவரை ஒட்டிச் செல்வதைத் தடுக்கிறது. மேலும் 'ஹிஜ்ர் அல்-யமாமா' (புறாக் கூண்டு) என்பதும் தடுத்தல் என்ற பொருளிலிருந்தே வந்தது. ஒரு நீதிபதி ஒருவரது செல்வத்தைப் பயன்படுத்துவதை முடக்கும்போது, \"ஹஜர அல்-ஹாகிம் (நீதிபதி தடுத்தார்)\" என்று கூறப்படுகிறது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَيَقُولُونَ حِجْراً مَّحْجُوراً\n\r\n\n\r\n(மேலும் அவர்கள், \"விலக்கப்பட்ட தடையாகும்\" (ஹிஜ்ர் மஹ்ஜூர்) என்று கூறுவார்கள்.) (25:22). இந்த உதாரணங்கள் அனைத்தும் வெவ்வேறு சூழல்களைக் குறிக்கின்றன என்றாலும் அவற்றின் அடிப்படைப் பொருள் ஒன்றுதான். இங்கு குறிப்பிடப்பட்டுள்ள சத்தியம், வணக்க வழிபாட்டு நேரங்களையும் ஹஜ், தொழுகை போன்ற வணக்கச் செயல்களையும் குறிக்கிறது. அல்லாஹ்வின் இறையச்சமுள்ள அடியார்கள் அவனது திருப்தியை நாடி, பணிவோடு செய்யும் இத்தகைய வணக்கங்கள் அவனை நெருங்குவதற்கான வழிகளாகும்.\n\r\n\n\r\nஆது கூட்டத்தாரின் அழிவைப் பற்றிக் குறிப்பிடுதல்\n\r\n\n\r\nஇறையச்சமுள்ள மக்களையும் அவர்களின் வணக்கங்களையும் குறிப்பிட்ட பிறகு, அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ\n\r\n\n\r\n(உமது இறைவன் ஆது கூட்டத்தாரை என்ன செய்தான் என்பதை நீர் பார்க்கவில்லையா?) இவர்கள் கலகக்காரர்களாகவும், கீழ்ப்படியாதவர்களாகவும், ஆணவம் கொண்டவர்களாகவும் இருந்தார்கள். அல்லாஹ்வின் கட்டளைகளை மீறி, அவனது தூதர்களையும் வேதங்களையும் நிராகரித்தார்கள். எனவே, அவர்களை அல்லாஹ் எப்படி அழித்தான், நிர்மூலமாக்கிப் பிற்காலத்தவர் பேசும் ஒரு பாடமாக ஆக்கினான் என்பதை அல்லாஹ் இங்கே குறிப்பிடுகிறான். அவன் கூறுகிறான்:\n\r\n\n\r\nأَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ - إِرَمَ ذَاتِ الْعِمَادِ\n\r\n\n\r\n(உமது இறைவன் ஆது கூட்டத்தாரை - தூண்களையுடைய இரம் (நகர) வாசிகளை - என்ன செய்தான் என்பதை நீர் பார்க்கவில்லையா?) இவர்கள் ஆது கூட்டத்தின் முதல் மக்கள் ஆவர். இவர்கள் ஆத் பின் இரம் பின் அவ்ஸ் பின் ஸாம் பின் நூஹ் (அலை) அவர்களின் வழித்தோன்றல்கள் என்று இப்னு இஸ்ஹாக் கூறுகிறார். இவர்களிடமே அல்லாஹ் தனது தூதர் ஹூத் (அலை) அவர்களை அனுப்பினான். ஆனால் அவர்கள் அவரைப் பொய்யாக்கி எதிர்த்தார்கள். எனவே அல்லாஹ் ஹூத் (அலை) அவர்களையும் அவருடன் ஈமான் கொண்டவர்களையும் காப்பாற்றிவிட்டு, மற்றவர்களைக் கடும் சீற்றத்துடன் வீசிய காற்றினால் அழித்தான்.\n\r\n\n\r\nسَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَثَمَـنِيَةَ أَيَّامٍ حُسُوماً فَتَرَى الْقَوْمَ فِيهَا صَرْعَى كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍ - فَهَلْ تَرَى لَهُم مِّن بَاقِيَةٍ\n\r\n\n\r\n(அதனை அல்லாஹ் தொடர்ந்து ஏழு இரவுகளும் எட்டுப் பகல்களும் அவர்கள் மீது ஏவினான்; அப்போது அந்த மக்கள் வேரோடு சாய்ந்த பேரீச்சை மரத்தின் உடல் பகுதிகளைப் போல் வீழ்ந்து கிடப்பதை நீர் பார்த்திருப்பீர். அவர்களில் எவராவது எஞ்சியிருப்பதை நீர் காண்கிறீரா?) (69:7-8). விசுவாசிகள் அவர்களின் முடிவிலிருந்து பாடம் பெற வேண்டும் என்பதற்காக அல்லாஹ் அவர்களின் வரலாற்றைக் குர்ஆனில் பல இடங்களில் குறிப்பிட்டுள்ளான். பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِرَمَ ذَاتِ الْعِمَادِ\n\r\n\n\r\n(தூண்களையுடைய இரம்.) இது அவர்கள் யார் என்பதைத் தெளிவுபடுத்தும் கூடுதல் விளக்கமாகும்.\n\r\n\n\r\nذَاتِ الْعِمَادِ\n\r\n\n\r\n(தூண்களையுடைய) என்பதற்கு விளக்கம் என்னவெனில், அவர்கள் உறுதியான தூண்களின் மேல் அமைக்கப்பட்ட உயர்ந்த வீடுகளில் வாழ்ந்தார்கள். அவர்கள் தங்கள் காலத்தில் உடல் வலிமையிலும் அதிகாரத்திலும் மற்றவர்களை விட மிக ஆற்றல் வாய்ந்தவர்களாக இருந்தார்கள். எனவே, ஹூத் (அலை) அவர்கள் அல்லாஹ் அவர்களுக்கு வழங்கிய இந்த அருளை நினைவூட்டி, அவர்களைப் படைத்த இறைவனுக்குக் கீழ்ப்படிவதற்காக இந்த வலிமையைப் பயன்படுத்துமாறு கூறினார்கள்:\n\r\n\n\r\nوَاذكُرُواْ إِذْ جَعَلَكُمْ خُلَفَآءَ مِن بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِى الْخَلْقِ بَسْطَةً فَاذْكُرُواْ ءَالآءَ اللَّهِ لَعَلَّكُمْ تُفْلِحُونَ\n\n\r\n\n(நூஹ் (அலை) உடைய சமூகத்தாருக்குப் பின் உங்களை அவன் பிரதிநிதிகளாக ஆக்கியதையும், உடல் அமைப்பில் உங்களை அவன் மேம்படுத்தியதையும் நினைத்துப் பாருங்கள். நீங்கள் வெற்றி பெறுவதற்காக அல்லாஹ்வின் அருட்கொடைகளை நினைவுகூருங்கள்.) (7:69). அல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\nفَأَمَّا عَادٌ فَاسْتَكْبَرُواْ فِى الاٌّرْضِ بِغَيْرِ الْحَقِّ وَقَالُواْ مَنْ أَشَدُّ مِنَّا قُوَّةً أَوَلَمْ يَرَوْاْ أَنَّ اللَّهَ الَّذِى خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةً\n\r\n\n\r\n(ஆது சமூகத்தாரோ, அவர்கள் பூமியில் அநியாயமாகப் பெருமையடித்து, \"வலிமையில் எங்களை விடச் சிறந்தவர் யார்?\" என்று கேட்டார்கள். அவர்களைப் படைத்த அல்லாஹ், அவர்களை விட வலிமையில் சிறந்தவன் என்பதை அவர்கள் உணரவில்லையா?) (41:15). மேலும் அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\nالَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى الْبِلَادِ\n\r\n\n\r\n(அவர்களைப் போன்றவர்கள் தேசங்களில் (இதற்கு முன்) படைக்கப்படவில்லை.) அதாவது அவர்களின் வலிமை, அதிகாரம் மற்றும் உடல் அமைப்பைப் போன்றவர்கள் அந்தத் தேசத்தில் வேறு யாரும் படைக்கப்பட்டதில்லை. முஜாஹித் (ரழி) அவர்கள், \"இரம் என்பது ஒரு பழங்கால சமூகமாகும்; அவர்களே ஆது கூட்டத்தின் முதல் மக்கள்\" என்று கூறினார்கள். கதாதா பின் திஆமா மற்றும் அஸ்-ஸுத்தீ ஆகிய இருவரும், \"நிச்சயமாக இரம் என்பது ஆது கூட்டத்தாரின் ஆட்சி பீடத்தைக் குறிக்கிறது\" என்றனர். இக்கூற்று வலிமையானதாகும்.\n\r\n\n\r\nالَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى الْبِلَادِ\n\r\n\n\r\n(அவர்களைப் போன்றவர்கள் தேசங்களில் படைக்கப்படவில்லை.) என்பதில் உள்ள பிரதிப்பெயர்ச்சொல் அவர்கள் அமைத்த தூண்களைக் குறிப்பதாக இப்னு ஸைத் கருதினார். \"அவர்கள் மலைகளுக்கு இடையில் மிக உயர்ந்த தூண்களைக் கட்டினார்கள், அதுபோன்றவை அந்தத் தேசத்தில் இதற்கு முன் கட்டப்பட்டதில்லை\" என்று அவர் கூறினார். இருப்பினும், கதாதா மற்றும் இப்னு ஜரீர் ஆகியோர் இது ஆது கோத்திரத்தைக் குறிக்கிறது என்றே கருதினார்கள். அதாவது, அந்தக் காலத்தில் அவர்களைப் போன்ற ஒரு பலமான கோத்திரம் பூமியில் படைக்கப்பட்டதில்லை என்பதே இதன் பொருள். இதுவே சரியான கருத்தாகும். இப்னு ஸைதின் கருத்து பலவீனமானது; ஏனெனில் அல்லாஹ் தூண்களை நாடியிருந்தால் \"உருவாக்கப்படவில்லை\" என்று கூறியிருப்பான், ஆனால் அவன் \"படைக்கப்படவில்லை\" (லெம் யுக்லக்) என்றே கூறியுள்ளான்:\n\r\n\n\r\nلَمْ يُخْلَقْ مِثْلُهَا فِى الْبِلَادِ\n\r\n\n\r\n(அவர்களைப் போன்றவர்கள் தேசங்களில் படைக்கப்படவில்லை.) பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَثَمُودَ الَّذِينَ جَابُواْ الصَّخْرَ بِالْوَادِ\n\r\n\n\r\n(பள்ளத்தாக்கில் பாறைகளைக் குடைந்த (ஜாபு) ஸமூத் கூட்டத்தாரையும்.) அதாவது அவர்கள் பள்ளத்தாக்குகளில் உள்ள பாறைகளை வெட்டி வீடுகளாக அமைத்தார்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள், \"அவர்கள் பாறைகளைச் செதுக்கிக் குடைந்தார்கள்\" என்று கூறினார்கள். முஜாஹித், கதாதா, அத்-தஹ்ஹாக் மற்றும் இப்னு ஸைத் ஆகியோரும் இதையே கூறினார்கள். அரபு மொழியில் ஆடையைத் தைப்பதற்காகத் துளை இடுவதை 'ஜைப்' என்பார்கள்; அதுவும் 'ஜாபு' என்ற சொல்லிலிருந்தே வந்தது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَتَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتاً فَـرِهِينَ\n\r\n\n\r\n(மேலும் நீங்கள் மலைகளைத் திறமையுடன் குடைந்து வீடுகளை அமைத்துக் கொள்கிறீர்கள்.) (26:149)\n\r\n\n\r\nஃபிர்அவ்னைப் பற்றிய ஒரு குறிப்பு\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَفِرْعَوْنَ ذِى الْأَوْتَادِ\n\r\n\n\r\n(மேலும் ஆணிகளுடைய (அல்-அவ்தாத்) ஃபிர்அவ்னையும்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"அல்-அவ்தாத் என்பது அவனது கட்டளைகளைச் செயல்படுத்திய அவனது படைகளைக் குறிக்கும்\" என்று கூறியதாக அல்-அவ்ஃபீ அறிவிக்கின்றார்கள். ஃபிர்அவ்ன் மக்களைத் தண்டிக்கும்போது அவர்களின் கைகளிலும் கால்களிலும் இரும்பு முளைகளை (ஆணிகளை) அடித்துத் தொங்கவிடுவான் என்றும் ஒரு கருத்து உள்ளது. முஜாஹித் (ரழி) அவர்களும், \"அவன் மக்களை முளைகளில் அடித்துத் தண்டிப்பான்\" என்று கூறினார்கள். ஸஈத் பின் ஜுபைர், அல்-ஹஸன் மற்றும் அஸ்-ஸுத்தீ ஆகியோரும் இதையே கூறியுள்ளனர். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nالَّذِينَ طَغَوْاْ فِى الْبِلَادِ - فَأَكْثَرُواْ فِيهَا الْفَسَادَ\n\r\n\n\r\n(அவர்கள் தேசங்களில் வரம்பு மீறிச் சென்றார்கள். மேலும் அதில் பெரும் குழப்பத்தை விளைவித்தார்கள்.) அதாவது அவர்கள் ஆணவத்துடன் கலகம் செய்து, பூமியில் சீர்கேடுகளை உண்டாக்கி மக்களுக்குத் தீங்கு செய்தார்கள்.\n\r\n\n\r\nفَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ\n\r\n\n\r\n(ஆகவே, உமது இறைவன் அவர்கள் மீது பல்வேறு வகையான கடுமையான வேதனைகளை இறக்கினான்.) அதாவது, அல்லாஹ் வானத்திலிருந்து அவர்கள் மீது தண்டனையை இறக்கினான்; குற்றவாளிகளால் தப்பிக்க முடியாத ஒரு வேதனையால் அவர்களை அழித்தான்.\n\r\n\n\r\nஇறைவன் எப்போதும் கண்காணிப்பவன்\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nإِنَّ رَبَّكَ لَبِالْمِرْصَادِ\n\r\n\n\r\n(நிச்சயமாக, உமது இறைவன் எப்போதும் கண்காணிப்பவனாக இருக்கிறான்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"அவன் அனைத்தையும் செவியேற்கிறான், பார்க்கிறான்\" என்று இதற்கு விளக்கமளித்தார்கள். அதாவது, தனது படைப்புகள் செய்வதை அல்லாஹ் உன்னிப்பாகக் கவனிக்கிறான்; அவர்கள் செய்த செயல்களுக்கு ஏற்ப இவ்வுலகிலும் மறுமையிலும் அவர்களுக்குப் பிரதிபலன் வழங்குவான். அல்லாஹ் அனைத்துப் படைப்புகளையும் தன் முன் கொண்டு வந்து நீதியுடன் தீர்ப்பளிப்பான். அவன் அநீதிக்கும் கொடுங்கோன்மைக்கும் அப்பாற்பட்டவன் என்பதால், ஒவ்வொருவருக்கும் அவரவர் தகுதிக்குரிய கூலியை வழங்குவான்."},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=20\" class=\"link\">89:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:20 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=20\" class=\"link\">89:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:20 ஐ பார்க்கவும்"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=20\" class=\"link\">89:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:20 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=20\" class=\"link\">89:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:20 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=20\" class=\"link\">89:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:20 ஐ பார்க்கவும்"},"20":{"html":"<strong>செல்வமும் வறுமையும் அடியானுக்கு ஒரு சோதனையாகவும், கண்ணியமாகவோ அல்லது இழிவாகவோ அமைகின்றன</strong><br />\r\n<br />\r\nஅல்லாஹ் மனிதனின் ஒரு தவறான எண்ணத்தை மறுக்கிறான். அதாவது, அல்லாஹ் ஒருவனைச் சோதிப்பதற்காக அவனுக்கு ஏராளமான வாழ்வாதாரங்களை வழங்கினால், அது தன்னை அல்லாஹ் கண்ணியப்படுத்திவிட்டதாக அவன் கருதுகிறான். ஆனால் உண்மை அதுவல்ல; மாறாக, அது ஒரு சோதனையும் ஒரு பரீட்சையுமே ஆகும். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَيَحْسَبُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّمَا</span> <span class=\"quran-arabic-font text-success\">نُمِدُّهُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَّالٍ</span> <span class=\"quran-arabic-font text-success\">وَبَنِينَ</span> - <span class=\"quran-arabic-font text-success\">نُسَارِعُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْخَيْرَاتِ</span> <span class=\"quran-arabic-font text-success\">بَل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَشْعُرُونَ</span><br />\r\n<br />\r\n(நாம் அவர்களுக்கு வழங்கும் செல்வங்கள் மற்றும் பிள்ளைகளைக் கொண்டு அவர்களுக்கு நன்மைகளை விரைந்து செய்கிறோம் என்று அவர்கள் எண்ணுகிறார்களா? இல்லை, அவர்கள் அதனை உணரவில்லை.) (<a href=\"qurandisp.php?sura=23&ayah=55\" class=\"link\">23:55</a>-56) அதேபோல், மற்றொரு கோணத்தில், அல்லாஹ் ஒருவனின் வாழ்வாதாரத்தைச் சுருக்கி அவனைச் சோதித்தால், அல்லாஹ் தன்னை இழிவுபடுத்திவிட்டதாக அவன் நம்புகிறான். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَلاَّ</span><br />\r\n<br />\r\n(இல்லை!) அதாவது, அவன் கருதுவது போல் இந்த விஷயத்திலோ அல்லது அந்த விஷயத்திலோ நிலைமை அப்படி இல்லை. ஏனெனில், நிச்சயமாக அல்லாஹ் தான் நேசிப்பவர்களுக்கும் செல்வத்தை வழங்குகிறான், நேசிக்காதவர்களுக்கும் வழங்குகிறான். அவ்வாறே, அவன் தான் நேசிப்பவர்களுக்கும் வாழ்வாதாரத்தைச் சுருக்குகிறான், நேசிக்காதவர்களுக்கும் சுருக்குகிறான். இங்கு அடிப்படையான விஷயம் என்னவென்றால், இரண்டு நிலைகளிலும் அல்லாஹ்வுக்குக் கீழ்ப்படிய வேண்டும் என்பதுதான். ஒருவன் செல்வந்தனாக இருந்தால், அதற்காக அவன் அல்லாஹ்வுக்கு நன்றி செலுத்த வேண்டும். அவன் ஏழையாக இருந்தால், அவன் பொறுமையைக் கடைப்பிடிக்க வேண்டும்.<br />\r\n<br />\r\n<strong>செல்வம் விஷயத்தில் அடியான் செய்யும் தீய செயல்கள்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تُكْرِمُونَ</span> <span class=\"quran-arabic-font text-success\">الْيَتِيمَ</span>-<br />\r\n<br />\r\n(மாறாக, நீங்கள் அநாதைகளைக் கண்ணியப்படுத்துவதில்லை!) இதில் அநாதைகளைக் கண்ணியமாக நடத்த வேண்டும் என்ற கட்டளை அடங்கியுள்ளது. சஹ்ல் பின் ஸஅத் (ரழி) அவர்கள் அறிவிப்பதாக அபூ தாவூத் பதிவு செய்துள்ளார்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">وَكَافِلُ</span> <span class=\"quran-arabic-font text-success\">الْيَتِيمِ</span> <span class=\"quran-arabic-font text-success\">كَهَاتَيْنِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّة</span>»<br />\r\n<br />\r\n(\"நானும் அநாதையைப் பராமரிப்பவரும் சொர்க்கத்தில் இவ்விரண்டைப் போல் இருப்போம்.\") இவ்வாறு கூறியபடி அவர்கள் தமது நடு விரலையும் ஆள்காட்டி விரலையும் ஒன்றாகச் சேர்த்து காட்டினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَحَاضُّونَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">طَعَامِ</span> <span class=\"quran-arabic-font text-success\">الْمِسْكِينِ</span>-<br />\r\n<br />\r\n(மேலும், மிஸ்கீன்களுக்கு (ஏழைகளுக்கு) உணவளிக்குமாறு நீங்கள் ஒருவரையொருவர் தூண்டுவதில்லை!) அதாவது, ஏழைகளிடமும் தேவையுடையவர்களிடமும் கருணை காட்டும்படி அவர்கள் கட்டளையிடுவதில்லை; அவ்வாறு செய்யும்படி ஒருவரையொருவர் ஊக்குவிப்பதும் இல்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَأْكُلُونَ</span> <span class=\"quran-arabic-font text-success\">التُّرَاثَ</span><br />\r\n<br />\r\n(மேலும், நீங்கள் துராஸை (வாரிசுரிமைச் சொத்துக்களை) விழுங்குகிறீர்கள்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَكْلاً</span> <span class=\"quran-arabic-font text-success\">لَّمّاً</span><br />\r\n<br />\r\n(பேராசையுடன் விழுங்குதல்.) அதாவது, ஹலாலானதா அல்லது ஹராமாவா என்று பாராமல், எந்த வழியில் முடியுமோ அந்த வழியில் அதனைத் தங்களுக்குச் சொந்தமாக்கிக் கொள்கிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتُحِبُّونَ</span> <span class=\"quran-arabic-font text-success\">الْمَالَ</span> <span class=\"quran-arabic-font text-success\">حُبّاً</span> <span class=\"quran-arabic-font text-success\">جَمّاً</span><br />\r\n<br />\r\n(மேலும் நீங்கள் செல்வத்தை ஜம்மா என்ற அபரிமிதமான காதலுடன் நேசிக்கிறீர்கள்.) அதாவது, அளவுக்கு அதிகமாக. இது அவர்களில் சிலரின் தீய குணங்களை மேலும் அதிகப்படுத்துகிறது.<br />\r\n<br />","text":"செல்வமும் வறுமையும் அடியானுக்கு ஒரு சோதனையாகவும், கண்ணியமாகவோ அல்லது இழிவாகவோ அமைகின்றன\n\r\n\n\r\nஅல்லாஹ் மனிதனின் ஒரு தவறான எண்ணத்தை மறுக்கிறான். அதாவது, அல்லாஹ் ஒருவனைச் சோதிப்பதற்காக அவனுக்கு ஏராளமான வாழ்வாதாரங்களை வழங்கினால், அது தன்னை அல்லாஹ் கண்ணியப்படுத்திவிட்டதாக அவன் கருதுகிறான். ஆனால் உண்மை அதுவல்ல; மாறாக, அது ஒரு சோதனையும் ஒரு பரீட்சையுமே ஆகும். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nأَيَحْسَبُونَ أَنَّمَا نُمِدُّهُمْ بِهِ مِن مَّالٍ وَبَنِينَ - نُسَارِعُ لَهُمْ فِي الْخَيْرَاتِ بَل لاَّ يَشْعُرُونَ\n\r\n\n\r\n(நாம் அவர்களுக்கு வழங்கும் செல்வங்கள் மற்றும் பிள்ளைகளைக் கொண்டு அவர்களுக்கு நன்மைகளை விரைந்து செய்கிறோம் என்று அவர்கள் எண்ணுகிறார்களா? இல்லை, அவர்கள் அதனை உணரவில்லை.) (23:55-56) அதேபோல், மற்றொரு கோணத்தில், அல்லாஹ் ஒருவனின் வாழ்வாதாரத்தைச் சுருக்கி அவனைச் சோதித்தால், அல்லாஹ் தன்னை இழிவுபடுத்திவிட்டதாக அவன் நம்புகிறான். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nكَلاَّ\n\r\n\n\r\n(இல்லை!) அதாவது, அவன் கருதுவது போல் இந்த விஷயத்திலோ அல்லது அந்த விஷயத்திலோ நிலைமை அப்படி இல்லை. ஏனெனில், நிச்சயமாக அல்லாஹ் தான் நேசிப்பவர்களுக்கும் செல்வத்தை வழங்குகிறான், நேசிக்காதவர்களுக்கும் வழங்குகிறான். அவ்வாறே, அவன் தான் நேசிப்பவர்களுக்கும் வாழ்வாதாரத்தைச் சுருக்குகிறான், நேசிக்காதவர்களுக்கும் சுருக்குகிறான். இங்கு அடிப்படையான விஷயம் என்னவென்றால், இரண்டு நிலைகளிலும் அல்லாஹ்வுக்குக் கீழ்ப்படிய வேண்டும் என்பதுதான். ஒருவன் செல்வந்தனாக இருந்தால், அதற்காக அவன் அல்லாஹ்வுக்கு நன்றி செலுத்த வேண்டும். அவன் ஏழையாக இருந்தால், அவன் பொறுமையைக் கடைப்பிடிக்க வேண்டும்.\n\r\n\n\r\nசெல்வம் விஷயத்தில் அடியான் செய்யும் தீய செயல்கள்\n\r\n\n\r\nஅல்லாஹ் கூறினான்,\n\r\n\n\r\nبَل لاَّ تُكْرِمُونَ الْيَتِيمَ-\n\r\n\n\r\n(மாறாக, நீங்கள் அநாதைகளைக் கண்ணியப்படுத்துவதில்லை!) இதில் அநாதைகளைக் கண்ணியமாக நடத்த வேண்டும் என்ற கட்டளை அடங்கியுள்ளது. சஹ்ல் பின் ஸஅத் (ரழி) அவர்கள் அறிவிப்பதாக அபூ தாவூத் பதிவு செய்துள்ளார்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَنَا وَكَافِلُ الْيَتِيمِ كَهَاتَيْنِ فِي الْجَنَّة»\n\r\n\n\r\n(\"நானும் அநாதையைப் பராமரிப்பவரும் சொர்க்கத்தில் இவ்விரண்டைப் போல் இருப்போம்.\") இவ்வாறு கூறியபடி அவர்கள் தமது நடு விரலையும் ஆள்காட்டி விரலையும் ஒன்றாகச் சேர்த்து காட்டினார்கள்.\n\r\n\n\r\nوَلاَ تَحَاضُّونَ عَلَى طَعَامِ الْمِسْكِينِ-\n\r\n\n\r\n(மேலும், மிஸ்கீன்களுக்கு (ஏழைகளுக்கு) உணவளிக்குமாறு நீங்கள் ஒருவரையொருவர் தூண்டுவதில்லை!) அதாவது, ஏழைகளிடமும் தேவையுடையவர்களிடமும் கருணை காட்டும்படி அவர்கள் கட்டளையிடுவதில்லை; அவ்வாறு செய்யும்படி ஒருவரையொருவர் ஊக்குவிப்பதும் இல்லை.\n\r\n\n\r\nوَتَأْكُلُونَ التُّرَاثَ\n\r\n\n\r\n(மேலும், நீங்கள் துராஸை (வாரிசுரிமைச் சொத்துக்களை) விழுங்குகிறீர்கள்.)\n\r\n\n\r\nأَكْلاً لَّمّاً\n\r\n\n\r\n(பேராசையுடன் விழுங்குதல்.) அதாவது, ஹலாலானதா அல்லது ஹராமாவா என்று பாராமல், எந்த வழியில் முடியுமோ அந்த வழியில் அதனைத் தங்களுக்குச் சொந்தமாக்கிக் கொள்கிறார்கள்.\n\r\n\n\r\nوَتُحِبُّونَ الْمَالَ حُبّاً جَمّاً\n\r\n\n\r\n(மேலும் நீங்கள் செல்வத்தை ஜம்மா என்ற அபரிமிதமான காதலுடன் நேசிக்கிறீர்கள்.) அதாவது, அளவுக்கு அதிகமாக. இது அவர்களில் சிலரின் தீய குணங்களை மேலும் அதிகப்படுத்துகிறது."},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=30\" class=\"link\">89:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:30 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=30\" class=\"link\">89:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:30 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=30\" class=\"link\">89:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:30 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=30\" class=\"link\">89:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:30 ஐ பார்க்கவும்"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=30\" class=\"link\">89:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:30 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=30\" class=\"link\">89:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:30 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=30\" class=\"link\">89:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:30 ஐ பார்க்கவும்"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=30\" class=\"link\">89:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:30 ஐ பார்க்கவும்"},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=89&ayah=30\" class=\"link\">89:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 89:30 ஐ பார்க்கவும்"},"30":{"html":"<strong>மறுமை நாளில் ஒவ்வொருவரும் தாம் செய்த நன்மை அல்லது தீமைக்கு ஏற்ப கூலி வழங்கப்படுவார்கள்</strong><br />\r\n<br />\r\n1. மறுமை நாளில் நிகழவிருக்கும் பெரும் திடுக்கிடும் நிகழ்வுகளைப் பற்றி அல்லாஹ் தெரிவிக்கிறான். அவன் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَلاَّ</span><br />\r\n<br />\r\n(வேண்டாம்!) அதாவது, உண்மையாகவே.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">دُكَّتِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">دَكّاً</span> <span class=\"quran-arabic-font text-success\">دَكّاً</span><br />\r\n<br />\r\n(பூமி தூள் தூளாகத் தகர்க்கப்படும் போது.) அதாவது, பூமியும் மலைகளும் தகர்க்கப்பட்டு, சமதளமாக்கப்படும். படைப்பினங்கள் தங்களின் இறைவனுக்காகத் தங்களது மண்ணறைகளிலிருந்து (கப்ருகளிலிருந்து) எழுப்பப்படுவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَآءَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">وَالْمَلَكُ</span> <span class=\"quran-arabic-font text-success\">صَفّاً</span> <span class=\"quran-arabic-font text-success\">صَفّاً</span><br />\r\n<br />\r\n(உமது இறைவன் வருவான்; மேலும் வானவர்கள் அணிவகுத்து வருவார்கள்) அதாவது, தனது படைப்பினங்களுக்கு இடையில் தீர்ப்பு வழங்குவதற்காக. ஆதம் (அலை) அவர்களின் மக்களில் சிறந்தவரான முஹம்மது (ஸல்) அவர்களிடம் மக்கள் சென்று அல்லாஹ்விடம் பரிந்துரை (ஷஃபாஅத்) செய்யுமாறு கோரிய பிறகு இது நிகழும். மக்கள் மற்ற மாபெரும் தூதர்களிடம் (அலை) ஒருவர்பின் ஒருவராகச் சென்று கோரிக்கை விடுத்த பின்னரே இது நடக்கும். ஆனால் அவர்கள் அனைவரும் \"என்னால் இதை உங்களுக்காகச் செய்ய முடியாது\" என்று கூறிவிடுவார்கள். இறுதியில் மக்களின் இந்த வேண்டுகோள் முஹம்மது (ஸல்) அவர்களை வந்தடையும். அப்போது அவர்கள் (ஸல்), \"நான் இதைச் செய்கிறேன், நான் இதைச் செய்கிறேன்\" என்று கூறுவார்கள். பிறகு அவர்கள் சென்று அல்லாஹ்விடம் பரிந்துரை செய்வார்கள். அப்போது தீர்ப்பு வழங்கும் நேரம் வந்திருக்கும், அல்லாஹ்வும் அதற்காகப் பரிந்துரை செய்ய அவர்களுக்கு அனுமதி வழங்குவான். இதுவே முதலாவது பரிந்துரையாகும். இதுவே 'மகாமு மஹ்மூத்' (புகழுக்குரிய இடம்) ஆகும்; இதைப் பற்றி ஸூரா ஸுப்ஹானில் (அல்-இஸ்ரா) ஏற்கனவே விளக்கப்பட்டுள்ளது. அல்லாஹ் தான் நாடியவாறு தீர்ப்பு வழங்க வருவான். வானவர்களும் அவனுக்கு முன்னால் அணிவகுத்து வரிசை வரிசையாக வருவார்கள். பிறகு அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجِيءَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">بِجَهَنَّمَ</span><br />\r\n<br />\r\n(மேலும் அந்நாளில் நரகம் கொண்டு வரப்படும்.) இமாம் முஸ்லிம் பின் அல்-ஹஜ்ஜாஜ் அவர்கள் தனது ஸஹீஹ் நூலில் பதிவு செய்துள்ளார்கள்: அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يُؤْتَى</span> <span class=\"quran-arabic-font text-success\">بِجَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">سَبْعُونَ</span> <span class=\"quran-arabic-font text-success\">أَلْفَ</span> <span class=\"quran-arabic-font text-success\">زِمَامٍ</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">زِمَامٍ</span> <span class=\"quran-arabic-font text-success\">سَبْعُونَ</span> <span class=\"quran-arabic-font text-success\">أَلْفَ</span> <span class=\"quran-arabic-font text-success\">مَلَكٍ</span> <span class=\"quran-arabic-font text-success\">يَجُرُّونَهَا</span>»<br />\r\n<br />\r\n(அந்நாளில் நரகம் கொண்டு வரப்படும். அதற்கு எழுபதாயிரம் கடிவாளங்கள் இருக்கும். ஒவ்வொரு கடிவாளத்தையும் எழுபதாயிரம் வானவர்கள் இழுத்து வருவார்கள்.) இதே செய்தியை அத்-திர்மிதி அவர்களும் பதிவு செய்துள்ளார்கள். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُ</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنُ</span><br />\r\n<br />\r\n(அந்நாளில் மனிதன் நினைவு கூர்வான்,) அதாவது, அவன் கடந்த காலத்திலும் சமீப காலத்திலும் செய்த தனது செயல்களை நினைவு கூர்வான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَّى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرَى</span><br />\r\n<br />\r\n(ஆனால் அந்த நினைவு அவனுக்கு எப்படிப் பயனளிக்கும்?) அதாவது, அப்போது நினைவு கூர்வதால் அவனுக்கு என்ன பயன் கிடைத்துவிடப் போகிறது?<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">لَيْتَنِي</span> <span class=\"quran-arabic-font text-success\">قَدَّمْتُ</span> <span class=\"quran-arabic-font text-success\">لِحَيَاتِى</span><br />\r\n<br />\r\n(அவன் கூறுவான்: \"அந்தோ! எனது (மறுமை) வாழ்விற்காக நான் நற்பலன்களை முற்படுத்தி இருக்க வேண்டுமே!\") அதாவது, அவன் பாவம் செய்தவனாக இருந்தால், தான் செய்த பாவங்களுக்காக வருந்துவான். அவன் கீழ்ப்படிந்து நடந்தவனாக இருந்தால், இன்னும் அதிகமான நற்செயல்களைச் செய்திருக்க வேண்டுமே என்று விரும்புவான். இது குறித்து இமாம் அஹ்மத் பின் ஹன்பல் அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் ஸஹாபாக்களில் ஒருவரான முஹம்மத் பின் அபீ அமீரா (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளார்கள்: \"ஓர் அடியான் தான் பிறந்த நாள் முதல் முதிய வயதில் மரணிக்கும் நாள் வரை அல்லாஹ்வுக்குக் கீழ்ப்படிந்து ஸஜ்தாவில் (சிரவணக்கத்தில்) விழுந்து கிடந்தாலும், மறுமை நாளில் அந்தச் செயலை அவன் அற்பமாகவே கருதுவான். இன்னும் அதிகமான நற்கூலிகளையும் பலன்களையும் பெறுவதற்காக மீண்டும் இவ்வுலக வாழ்விற்குத் திருப்பி அனுப்பப்பட வேண்டும் என்று அவன் விரும்புவான்.\" பிறகு அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَيَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُعَذِّبُ</span> <span class=\"quran-arabic-font text-success\">عَذَابَهُ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span><br />\r\n<br />\r\n(எனவே அந்நாளில் அவன் தண்டிப்பதைப் போன்று எவனும் தண்டிக்க மாட்டான்.) அதாவது, அல்லாஹ்வுக்கு மாறு செய்தவர்களை அவன் தண்டிப்பதைப் போல மிகக் கடுமையாகத் தண்டிக்கக்கூடியவர் எவருமில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُوثِقُ</span> <span class=\"quran-arabic-font text-success\">وَثَاقَهُ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span><br />\r\n<br />\r\n(மேலும் அவன் கட்டுவதைப் போன்று எவனும் கட்ட மாட்டான்.) அதாவது, இறைவனை நிராகரித்தவர்களை அஸ்-ஸபானிய்யாக்கள் (நரகத்தின் காவலர்கள்) தண்டிப்பதையும் கட்டுவதையும் விடக் கடுமையாக எவரும் தண்டிக்கவோ கட்டவோ முடியாது. இது படைப்பினங்களில் உள்ள குற்றவாளிகளுக்கும் அநியாயக்காரர்களுக்கும் உரியதாகும். தூய்மையான மற்றும் அமைதியான ஆன்மாவைப் பொறுத்தவரை - அது எப்போதும் சத்தியத்தின் மீது நிலைத்து அமைதியுடன் இருக்கும் - அதனிடம் இவ்வாறு கூறப்படும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيَّتُهَا</span> <span class=\"quran-arabic-font text-success\">النَّفْسُ</span> <span class=\"quran-arabic-font text-success\">الْمُطْمَئِنَّةُ</span> <span class=\"quran-arabic-font text-success\">ارْجِعِى</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّكِ</span><br />\r\n<br />\r\n(அமைதியுற்ற ஆன்மாவே! உனது இறைவனிடம் திரும்பிச் செல்.) அதாவது அவனது அருகாமைக்கும், அவனது நற்கூலிக்கும், அவன் தனது அடியார்களுக்காகச் சுவனத்தில் (ஜன்னத்தில்) தயார் செய்து வைத்திருப்பவற்றிற்கும் திரும்புவாயாக.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَّاضِيَةً</span><br />\r\n<br />\r\n(திருப்தியுற்ற நிலையில்) அதாவது தனக்குள்ளேயே திருப்தி அடைந்ததாக.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّرْضِيَّةً</span><br />\r\n<br />\r\n(அவனது திருப்தியைப் பெற்ற நிலையில்.) அதாவது, தான் அல்லாஹ்வைக் கொண்டு திருப்தியடைந்திருக்க, அல்லாஹ்வும் அதைக் கொண்டு திருப்தியடைந்து அதை மகிழ்விப்பான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَادْخُلِى</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">عِبَادِى</span><br />\r\n<br />\r\n(எனவே, எனது அடியார்களுள் இணைந்து விடு,) அதாவது அவர்களது வரிசையில் சேர்ந்து விடு.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَادْخُلِى</span> <span class=\"quran-arabic-font text-success\">جَنَّتِى</span><br />\r\n<br />\r\n(மேலும் எனது சுவனத்தில் நுழைந்து விடு!) இது மரண நேரத்திலும் மறுமை நாளிலும் அந்த ஆன்மாவிடம் கூறப்படும். ஒரு முஃமின் (இறைநம்பிக்கையாளர்) மரணிக்கும் போதும், அவர் தனது மண்ணறையிலிருந்து எழும்போதும் வானவர்கள் அவருக்கு நற்செய்தி கூறுவதைப் போன்றதே இதுவும் ஆகும். அதேபோல்தான் இங்கேயும் இந்தக் கூற்று அமைந்துள்ளது. இப்னு அபீ ஹாதிம் அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் வழியாக அல்லாஹ்வின் இந்த வசனத்தைப் பற்றிப் பதிவு செய்துள்ளார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيَّتُهَا</span> <span class=\"quran-arabic-font text-success\">النَّفْسُ</span> <span class=\"quran-arabic-font text-success\">الْمُطْمَئِنَّةُ</span> - <span class=\"quran-arabic-font text-success\">ارْجِعِى</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّكِ</span> <span class=\"quran-arabic-font text-success\">رَاضِيَةً</span> <span class=\"quran-arabic-font text-success\">مَّرْضِيَّةً</span><br />\r\n<br />\r\n(அமைதியுற்ற ஆன்மாவே! திருப்தியடைந்த நிலையிலும் அவனது திருப்தியைப் பெற்ற நிலையிலும் உனது இறைவனிடம் திரும்பிச் செல்!) அவர்கள் கூறினார்கள்: \"அபூபக்ர் (ரழி) அவர்கள் (நபி (ஸல்) அவர்களுடன்) அமர்ந்திருந்த போது இந்த வசனம் அருளப்பட்டது. அப்போது அவர்கள், 'அல்லாஹ்வின் தூதரே! இதை விடச் சிறந்தது எதுவுமில்லை!' என்று கூறினார்கள். அதற்கு நபி (ஸல்) அவர்கள் பதிலளித்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَمَا</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">سَيُقَالُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span>»<br />\r\n<br />\r\n(நிச்சயமாக இது உமக்குக் கூறப்படும்.)\" இத்துடன் ஸூரத்துல் ஃபஜ்ரின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் அருளும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />","text":"மறுமை நாளில் ஒவ்வொருவரும் தாம் செய்த நன்மை அல்லது தீமைக்கு ஏற்ப கூலி வழங்கப்படுவார்கள்\n\r\n\n\r\n1. மறுமை நாளில் நிகழவிருக்கும் பெரும் திடுக்கிடும் நிகழ்வுகளைப் பற்றி அல்லாஹ் தெரிவிக்கிறான். அவன் கூறுகிறான்,\n\r\n\n\r\nكَلاَّ\n\r\n\n\r\n(வேண்டாம்!) அதாவது, உண்மையாகவே.\n\r\n\n\r\nإِذَا دُكَّتِ الْأَرْضُ دَكّاً دَكّاً\n\r\n\n\r\n(பூமி தூள் தூளாகத் தகர்க்கப்படும் போது.) அதாவது, பூமியும் மலைகளும் தகர்க்கப்பட்டு, சமதளமாக்கப்படும். படைப்பினங்கள் தங்களின் இறைவனுக்காகத் தங்களது மண்ணறைகளிலிருந்து (கப்ருகளிலிருந்து) எழுப்பப்படுவார்கள்.\n\r\n\n\r\nوَجَآءَ رَبُّكَ وَالْمَلَكُ صَفّاً صَفّاً\n\r\n\n\r\n(உமது இறைவன் வருவான்; மேலும் வானவர்கள் அணிவகுத்து வருவார்கள்) அதாவது, தனது படைப்பினங்களுக்கு இடையில் தீர்ப்பு வழங்குவதற்காக. ஆதம் (அலை) அவர்களின் மக்களில் சிறந்தவரான முஹம்மது (ஸல்) அவர்களிடம் மக்கள் சென்று அல்லாஹ்விடம் பரிந்துரை (ஷஃபாஅத்) செய்யுமாறு கோரிய பிறகு இது நிகழும். மக்கள் மற்ற மாபெரும் தூதர்களிடம் (அலை) ஒருவர்பின் ஒருவராகச் சென்று கோரிக்கை விடுத்த பின்னரே இது நடக்கும். ஆனால் அவர்கள் அனைவரும் \"என்னால் இதை உங்களுக்காகச் செய்ய முடியாது\" என்று கூறிவிடுவார்கள். இறுதியில் மக்களின் இந்த வேண்டுகோள் முஹம்மது (ஸல்) அவர்களை வந்தடையும். அப்போது அவர்கள் (ஸல்), \"நான் இதைச் செய்கிறேன், நான் இதைச் செய்கிறேன்\" என்று கூறுவார்கள். பிறகு அவர்கள் சென்று அல்லாஹ்விடம் பரிந்துரை செய்வார்கள். அப்போது தீர்ப்பு வழங்கும் நேரம் வந்திருக்கும், அல்லாஹ்வும் அதற்காகப் பரிந்துரை செய்ய அவர்களுக்கு அனுமதி வழங்குவான். இதுவே முதலாவது பரிந்துரையாகும். இதுவே 'மகாமு மஹ்மூத்' (புகழுக்குரிய இடம்) ஆகும்; இதைப் பற்றி ஸூரா ஸுப்ஹானில் (அல்-இஸ்ரா) ஏற்கனவே விளக்கப்பட்டுள்ளது. அல்லாஹ் தான் நாடியவாறு தீர்ப்பு வழங்க வருவான். வானவர்களும் அவனுக்கு முன்னால் அணிவகுத்து வரிசை வரிசையாக வருவார்கள். பிறகு அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nوَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ\n\r\n\n\r\n(மேலும் அந்நாளில் நரகம் கொண்டு வரப்படும்.) இமாம் முஸ்லிம் பின் அல்-ஹஜ்ஜாஜ் அவர்கள் தனது ஸஹீஹ் நூலில் பதிவு செய்துள்ளார்கள்: அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يُؤْتَى بِجَهَنَّمَ يَوْمَئِذٍ لَهَا سَبْعُونَ أَلْفَ زِمَامٍ مَعَ كُلِّ زِمَامٍ سَبْعُونَ أَلْفَ مَلَكٍ يَجُرُّونَهَا»\n\r\n\n\r\n(அந்நாளில் நரகம் கொண்டு வரப்படும். அதற்கு எழுபதாயிரம் கடிவாளங்கள் இருக்கும். ஒவ்வொரு கடிவாளத்தையும் எழுபதாயிரம் வானவர்கள் இழுத்து வருவார்கள்.) இதே செய்தியை அத்-திர்மிதி அவர்களும் பதிவு செய்துள்ளார்கள். அல்லாஹ் கூறினான்:\n\r\n\n\r\nيَوْمَئِذٍ يَتَذَكَّرُ الإِنسَـنُ\n\r\n\n\r\n(அந்நாளில் மனிதன் நினைவு கூர்வான்,) அதாவது, அவன் கடந்த காலத்திலும் சமீப காலத்திலும் செய்த தனது செயல்களை நினைவு கூர்வான்.\n\r\n\n\r\nوَأَنَّى لَهُ الذِّكْرَى\n\r\n\n\r\n(ஆனால் அந்த நினைவு அவனுக்கு எப்படிப் பயனளிக்கும்?) அதாவது, அப்போது நினைவு கூர்வதால் அவனுக்கு என்ன பயன் கிடைத்துவிடப் போகிறது?\n\r\n\n\r\nيَقُولُ يَا لَيْتَنِي قَدَّمْتُ لِحَيَاتِى\n\r\n\n\r\n(அவன் கூறுவான்: \"அந்தோ! எனது (மறுமை) வாழ்விற்காக நான் நற்பலன்களை முற்படுத்தி இருக்க வேண்டுமே!\") அதாவது, அவன் பாவம் செய்தவனாக இருந்தால், தான் செய்த பாவங்களுக்காக வருந்துவான். அவன் கீழ்ப்படிந்து நடந்தவனாக இருந்தால், இன்னும் அதிகமான நற்செயல்களைச் செய்திருக்க வேண்டுமே என்று விரும்புவான். இது குறித்து இமாம் அஹ்மத் பின் ஹன்பல் அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் ஸஹாபாக்களில் ஒருவரான முஹம்மத் பின் அபீ அமீரா (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளார்கள்: \"ஓர் அடியான் தான் பிறந்த நாள் முதல் முதிய வயதில் மரணிக்கும் நாள் வரை அல்லாஹ்வுக்குக் கீழ்ப்படிந்து ஸஜ்தாவில் (சிரவணக்கத்தில்) விழுந்து கிடந்தாலும், மறுமை நாளில் அந்தச் செயலை அவன் அற்பமாகவே கருதுவான். இன்னும் அதிகமான நற்கூலிகளையும் பலன்களையும் பெறுவதற்காக மீண்டும் இவ்வுலக வாழ்விற்குத் திருப்பி அனுப்பப்பட வேண்டும் என்று அவன் விரும்புவான்.\" பிறகு அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nفَيَوْمَئِذٍ لاَّ يُعَذِّبُ عَذَابَهُ أَحَدٌ\n\r\n\n\r\n(எனவே அந்நாளில் அவன் தண்டிப்பதைப் போன்று எவனும் தண்டிக்க மாட்டான்.) அதாவது, அல்லாஹ்வுக்கு மாறு செய்தவர்களை அவன் தண்டிப்பதைப் போல மிகக் கடுமையாகத் தண்டிக்கக்கூடியவர் எவருமில்லை.\n\r\n\n\r\nوَلاَ يُوثِقُ وَثَاقَهُ أَحَدٌ\n\r\n\n\r\n(மேலும் அவன் கட்டுவதைப் போன்று எவனும் கட்ட மாட்டான்.) அதாவது, இறைவனை நிராகரித்தவர்களை அஸ்-ஸபானிய்யாக்கள் (நரகத்தின் காவலர்கள்) தண்டிப்பதையும் கட்டுவதையும் விடக் கடுமையாக எவரும் தண்டிக்கவோ கட்டவோ முடியாது. இது படைப்பினங்களில் உள்ள குற்றவாளிகளுக்கும் அநியாயக்காரர்களுக்கும் உரியதாகும். தூய்மையான மற்றும் அமைதியான ஆன்மாவைப் பொறுத்தவரை - அது எப்போதும் சத்தியத்தின் மீது நிலைத்து அமைதியுடன் இருக்கும் - அதனிடம் இவ்வாறு கூறப்படும்:\n\r\n\n\r\nيَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ارْجِعِى إِلَى رَبِّكِ\n\r\n\n\r\n(அமைதியுற்ற ஆன்மாவே! உனது இறைவனிடம் திரும்பிச் செல்.) அதாவது அவனது அருகாமைக்கும், அவனது நற்கூலிக்கும், அவன் தனது அடியார்களுக்காகச் சுவனத்தில் (ஜன்னத்தில்) தயார் செய்து வைத்திருப்பவற்றிற்கும் திரும்புவாயாக.\n\r\n\n\r\nرَّاضِيَةً\n\r\n\n\r\n(திருப்தியுற்ற நிலையில்) அதாவது தனக்குள்ளேயே திருப்தி அடைந்ததாக.\n\r\n\n\r\nمَّرْضِيَّةً\n\r\n\n\r\n(அவனது திருப்தியைப் பெற்ற நிலையில்.) அதாவது, தான் அல்லாஹ்வைக் கொண்டு திருப்தியடைந்திருக்க, அல்லாஹ்வும் அதைக் கொண்டு திருப்தியடைந்து அதை மகிழ்விப்பான்.\n\r\n\n\r\nفَادْخُلِى فِى عِبَادِى\n\r\n\n\r\n(எனவே, எனது அடியார்களுள் இணைந்து விடு,) அதாவது அவர்களது வரிசையில் சேர்ந்து விடு.\n\r\n\n\r\nوَادْخُلِى جَنَّتِى\n\r\n\n\r\n(மேலும் எனது சுவனத்தில் நுழைந்து விடு!) இது மரண நேரத்திலும் மறுமை நாளிலும் அந்த ஆன்மாவிடம் கூறப்படும். ஒரு முஃமின் (இறைநம்பிக்கையாளர்) மரணிக்கும் போதும், அவர் தனது மண்ணறையிலிருந்து எழும்போதும் வானவர்கள் அவருக்கு நற்செய்தி கூறுவதைப் போன்றதே இதுவும் ஆகும். அதேபோல்தான் இங்கேயும் இந்தக் கூற்று அமைந்துள்ளது. இப்னு அபீ ஹாதிம் அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் வழியாக அல்லாஹ்வின் இந்த வசனத்தைப் பற்றிப் பதிவு செய்துள்ளார்கள்:\n\r\n\n\r\nيَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ - ارْجِعِى إِلَى رَبِّكِ رَاضِيَةً مَّرْضِيَّةً\n\r\n\n\r\n(அமைதியுற்ற ஆன்மாவே! திருப்தியடைந்த நிலையிலும் அவனது திருப்தியைப் பெற்ற நிலையிலும் உனது இறைவனிடம் திரும்பிச் செல்!) அவர்கள் கூறினார்கள்: \"அபூபக்ர் (ரழி) அவர்கள் (நபி (ஸல்) அவர்களுடன்) அமர்ந்திருந்த போது இந்த வசனம் அருளப்பட்டது. அப்போது அவர்கள், 'அல்லாஹ்வின் தூதரே! இதை விடச் சிறந்தது எதுவுமில்லை!' என்று கூறினார்கள். அதற்கு நபி (ஸல்) அவர்கள் பதிலளித்தார்கள்:\n\r\n\n\r\n«أَمَا إِنَّهُ سَيُقَالُ لَكَ هَذَا»\n\r\n\n\r\n(நிச்சயமாக இது உமக்குக் கூறப்படும்.)\" இத்துடன் ஸூரத்துல் ஃபஜ்ரின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் அருளும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
